def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string s.
    If no such character exists, returns None.
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    for char in s:
        if char_count[char] == 1:
            return char
    return None
